class HibernateBootstrap {
    private static SessionFactory sf;
    static synchronized SessionFactory getSessionFactory() {
        if (sf == null) {
            sf = buildSessionFactory();
            Runtime.getRuntime().addShutdownHook(new Thread(sf::close));
        }
        return sf;
    }
}
